from pathlib import Path
import json
r=Path('.'); p=r/'composition'; d=p/'compositions'; d.mkdir(exist_ok=True)
css='''@font-face{font-family:Space Grotesk;src:url('assets/fonts/space-grotesk-latin-variable.woff2')}@font-face{font-family:Inter;src:url('assets/fonts/inter-latin-variable.woff2')}*{box-sizing:border-box}#root{position:absolute;inset:0;color:#09006C;font-family:Inter;background:#F7F7F7}h1,h2,p{margin:0}h1,h2{font-family:Space Grotesk;font-weight:700;letter-spacing:-3px}h1{font-size:104px;line-height:1.06}h2{font-size:76px;line-height:1.08}.eyebrow{font-size:25px;letter-spacing:4px;text-transform:uppercase;font-weight:700;color:#5C40FF;margin-bottom:24px}.sub{font-size:30px;line-height:1.5;color:#484365}.inner{padding:128px 170px;height:100%;position:relative}.topline{display:flex;align-items:center;gap:18px;margin-bottom:42px;font-size:24px;font-weight:700;letter-spacing:2px}.mark{width:48px;height:48px}.footer{position:absolute;bottom:65px;left:170px;right:170px;font-size:22px;display:flex;justify-content:space-between;color:#514B6B}.screen{position:absolute;left:930px;top:160px;width:820px;background:#fff;border:2px solid #D9D4EE;border-radius:24px;box-shadow:0 24px 70px #09006c14;overflow:hidden}.chrome{background:#EEEAFB;padding:22px 30px;font-size:23px;display:flex;justify-content:space-between}.screen-body{padding:35px}.screen h3{font-family:Space Grotesk;font-size:36px;margin:0 0 25px;letter-spacing:-1px}.row{display:flex;align-items:center;justify-content:space-between;padding:25px 0;border-bottom:1px solid #DDD8EA;font-size:28px}.pill{background:#E8E2FF;color:#35228A;padding:12px 19px;border-radius:12px;font-size:25px;font-weight:600}.button{padding:22px;background:#5C40FF;color:#fff;border-radius:12px;text-align:center;font-size:26px;font-weight:700}.small{font-size:22px;color:#514B6B}.white{color:#fff}.cursor{position:absolute;width:42px;height:55px;z-index:5}.tagline{font-size:32px;margin-top:25px}.bar{height:12px;border-radius:8px;background:#5C40FF}.feature{border-top:3px solid #5C40FF;padding-top:25px}.feature h3{font-family:Space Grotesk;font-size:35px;margin:0 0 25px;letter-spacing:-1px}.feature p{font-size:28px;line-height:1.75}.label{font-size:22px;font-weight:700;letter-spacing:1px;color:#514B6B}'''
scenes=[]
def scene(name,start,duration,body,motion=''):
 text=f'''<template><style>{css}</style><div id="root" data-composition-id="{name}" data-width="1920" data-height="1080"><div class="inner"><div id="{name}-content">{body}</div></div></div><script>const tl=gsap.timeline({{paused:true}});tl.fromTo('#{name}-content',{{opacity:0,y:22}},{{opacity:1,y:0,duration:0.4,ease:'power3.out'}},0.04);{motion}window.__timelines['{name}']=tl;</script></template>'''
 (d/f'{name}.html').write_text(text,encoding='utf-8'); scenes.append((name,start,duration))
top='<div class="topline"><img class="mark" src="assets/mark.png"/> CACU BUSINESS MANAGEMENT</div>'
scene('intro',0,3,'''<div style="display:flex;gap:100px;align-items:center;height:780px"><div style="width:790px"><div class="eyebrow">Built for Nigerian businesses</div><h1>Your business,<br>connected.</h1><p class="sub" style="margin-top:36px">Sales. Stock. Books. People.</p></div><div id="intro-logo" style="width:650px;padding:60px 20px;background:#F7F7F7"><img src="assets/logo.jpg" style="width:610px"/><p style="font-size:28px;margin-top:32px;text-align:center">Product · Service · Hybrid</p></div></div><div class="footer"><span>Meet CACU</span><span>Business management for MSMEs</span></div>''',"tl.fromTo('#intro-logo',{scale:0.95},{scale:1,duration:1.3,ease:'power2.out'},0.2);")
scene('sell',3,5.74,top+'''<div style="width:690px"><div class="eyebrow">01 / Every working day</div><h2>Sales &amp; stock.</h2><p class="sub" style="margin:30px 0 48px">From the counter<br>to the record.</p><div style="display:flex;gap:15px;flex-wrap:wrap"><span class="pill">Inventory</span><span class="pill">Invoices</span><span class="pill">Supplier bills</span></div></div><div class="screen" id="sell-screen"><div class="chrome"><span>CACU</span><span>POS Checkout</span></div><div class="screen-body"><h3>POS Checkout</h3><div class="small" style="background:#F3F0FA;padding:17px;border-radius:8px">Search inventory or scan SKU...</div><div class="row"><span>Milk, tin × 2</span><strong>₦1,300</strong></div><div class="row"><span>Noodles × 1</span><strong>₦500</strong></div><div class="row" style="border:0"><span>Total</span><strong>₦1,800</strong></div><div class="button" id="sell-button">Confirm &amp; Record Sale</div><div id="sell-confirm" style="margin-top:20px;color:#17633D;font-size:26px;font-weight:700">✓ Sale Recorded</div></div></div><svg class="cursor" id="sell-cursor" viewBox="0 0 35 45" style="left:1480px;top:670px"><path d="M3 2L3 38L13 29L20 43L27 39L20 26L33 25Z" fill="#09006C" stroke="white" stroke-width="2"/></svg><div class="footer"><span>Illustrative product walkthrough · Sample data</span><span>01 / 03</span></div>''',"tl.fromTo('#sell-screen',{y:30},{y:0,duration:0.5,ease:'power3.out'},0.12);tl.fromTo('#sell-cursor',{x:110,y:80},{x:0,y:0,duration:0.7,ease:'power2.out'},1.2);tl.fromTo('#sell-button',{scale:1},{scale:0.97,duration:0.12,yoyo:true,repeat:1},2.15);tl.fromTo('#sell-confirm',{opacity:0,y:8},{opacity:1,y:0,duration:0.3},2.5);")
scene('books',8.74,5.26,top+'''<div style="width:680px"><div class="eyebrow">02 / Know the numbers</div><h2>Transactions.<br>Clearer reports.</h2><p class="sub" style="margin:32px 0">Double-entry accounting.<br>Financial statements.<br>PDF &amp; Excel exports.</p><p class="small">Accounting activation required.</p></div><div class="screen" style="top:145px"><div class="chrome"><span>CACU</span><span>Financial Reports</span></div><div class="screen-body"><h3>Financial Reports</h3><div style="display:flex;gap:12px;font-size:21px;border-bottom:2px solid #DCD6FF;padding-bottom:20px"><b style="color:#5C40FF">Income Statement</b><span>Balance Sheet</span><span>Cash Flow</span></div><div class="small" style="margin-top:25px">Sample management statement</div><div class="row" id="books-row1"><span>Income</span><strong>₦480,000</strong></div><div class="row" id="books-row2"><span>Expenses</span><strong>₦320,000</strong></div><div class="row" id="books-row3" style="color:#35228A"><b>Net profit</b><strong>₦160,000</strong></div><div style="display:flex;gap:15px;margin-top:25px"><span class="pill">PDF</span><span class="pill">Excel</span></div></div></div><div class="footer"><span>Income Statement · Balance Sheet · Cash Flow Statement</span><span>02 / 03</span></div>''',"// beat-locked: report reveal at 8.74s\ntl.fromTo('#books-row1',{opacity:0,x:15},{opacity:1,x:0,duration:0.3},0.55);tl.fromTo('#books-row2',{opacity:0,x:15},{opacity:1,x:0,duration:0.3},1.1);tl.fromTo('#books-row3',{opacity:0,x:15},{opacity:1,x:0,duration:0.3},1.65);")
scene('team',14,7,top+'''<div class="eyebrow">03 / More than the counter</div><h2>Your team. Your controls.</h2><div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:55px;margin-top:70px"><div class="feature" id="team-hr"><h3>HR &amp; workforce</h3><p>Employees<br>Attendance<br>Payroll drafts</p><div class="small" style="margin-top:22px">No payroll payouts or posting.</div></div><div class="feature" id="team-roles"><h3>Access &amp; records</h3><p>User roles<br>Audit history<br>Secure uploads</p><div class="small" style="margin-top:22px">Business-scoped controls.</div></div><div class="feature" id="team-ai"><h3>CACU AI Assistant</h3><p>Business questions<br>Financial context<br>Reviewed close controls</p><div class="small" style="margin-top:22px">AI requires provider setup.</div></div></div><div class="footer"><span>Feature availability depends on configuration.</span><span>03 / 03</span></div>''',"tl.fromTo('#team-hr',{opacity:0,y:15},{opacity:1,y:0,duration:0.35},0.3);tl.fromTo('#team-roles',{opacity:0,y:15},{opacity:1,y:0,duration:0.35},0.85);tl.fromTo('#team-ai',{opacity:0,y:15},{opacity:1,y:0,duration:0.35},1.4);// beat-locked: subtle brand emphasis at 17.47s\ntl.fromTo('#team-ai',{borderTopColor:'#5C40FF'},{borderTopColor:'#09006C',duration:0.5},3.47);")
scene('outro',21,4,'''<div style="text-align:center;padding-top:95px"><img id="outro-logo" src="assets/logo.jpg" style="width:870px;height:auto"/><h2 style="margin-top:65px;font-size:78px">Your business, connected.</h2><p class="tagline">Product · Service · Hybrid</p><p class="small" style="margin-top:50px">Built for Nigerian businesses.</p></div><div class="footer"><span>Explore CACU</span><span>Illustrative walkthrough · Setup required for connected services</span></div>''',"tl.fromTo('#outro-logo',{scale:0.97},{scale:1,duration:1.1,ease:'power2.out'},0.1);")
variables=[{'id':'color-ground','type':'color','label':'Background','default':'#F7F7F7'},{'id':'color-ink','type':'color','label':'Text','default':'#09006C'},{'id':'color-accent','type':'color','label':'Accent','default':'#5C40FF'}]
hosts=''.join(f'<div id="{n}" class="clip" data-composition-id="{n}" data-composition-src="compositions/{n}.html" data-start="{s}" data-duration="{dur}" data-width="1920" data-height="1080" data-track-index="1" data-track-kind="graphics"></div>' for n,s,dur in scenes)
(p/'index.html').write_text('''<!doctype html><html lang="en" data-resolution="landscape" data-composition-variables='''+"'"+json.dumps(variables)+"'"+'''><head><meta charset="utf-8"><script src="assets/gsap.min.js"></script><style>*{margin:0;box-sizing:border-box}html,body{width:1920px;height:1080px;overflow:hidden;background:var(--color-ground,#F7F7F7)}.clip{position:absolute;inset:0}#root{position:relative;width:1920px;height:1080px}</style></head><body><div id="root" data-composition-id="main" data-start="0" data-duration="25" data-width="1920" data-height="1080">'''+hosts+'''<audio id="music" data-start="0" data-duration="25" data-track-index="10" data-volume="0.13" data-fade-in="0.45" data-fade-out="1.4" src="assets/music.mp3"></audio><audio id="voice" data-start="0.35" data-track-index="11" data-volume="1" src="assets/voiceover.wav"></audio><audio id="click" data-start="5.15" data-duration="0.2" data-track-index="12" data-volume="0.5" src="assets/click.ogg"></audio><audio id="drop" data-start="8.74" data-duration="0.3" data-track-index="13" data-volume="0.4" src="assets/drop.ogg"></audio></div><script>window.__timelines=window.__timelines||{};window.__timelines.main=gsap.timeline({paused:true});</script></body></html>''',encoding='utf-8')
(r/'share-copy.txt').write_text('Meet CACU: sales, stock, invoices, supplier bills, accounting and financial reports, connected for Nigerian businesses. With team controls, HR tools and a configurable AI assistant, CACU brings daily operations into one workspace.',encoding='utf-8')
print('Five editable scenes and share copy written.')
